  LOCAL
    Count : INTEGER := 0;
  END_LOCAL;

      IF NOT(EXISTS(Constraint)) THEN 
        RETURN(TRUE);
      END_IF;

      CASE Constraint OF
        IfcObjectTypeEnum.NOTDEFINED : RETURN(TRUE);
        IfcObjectTypeEnum.PRODUCT :
          BEGIN
